$(".all").click(function () {
    $(".img").show();
});

$(".paper").click(function () {
    $(".img").hide();
    $(".img.paper").show();
});

$(".magazine").click(function () {
    $(".img").hide();
    $(".img.magazine").show();
});

$(".logo").click(function () {
    $(".img").hide();
    $(".img.logo").show();
});